script:
// Redirect to the sitemap function while preserving the custom domain
const currentHost = window.location.host;
const params = new URLSearchParams(window.location.search);
const type = params.get('type') || 'index';

// Construct the sitemap function URL
const functionUrl = `https://rscowwmoeycyxmfslhme.supabase.co/functions/v1/sitemap?type=${type}`;

// Fetch and serve the sitemap with custom domain replacement
fetch(functionUrl, {
  headers: {
    'Origin': window.location.origin,
    'Referer': window.location.href
  }
})
.then(response => response.text())
.then(xml => {
  // Replace any Supabase URLs with the custom domain
  const correctedXml = xml.replace(/https:\/\/rscowwmoeycyxmfslhme\.supabase\.co/g, window.location.origin);

  // Set the content type and serve the XML
  document.open();
  document.write(correctedXml);
  document.close();

  // Set the proper content type
  if (document.contentType !== 'application/xml') {
    document.querySelector('html').setAttribute('content-type', 'application/xml');
  }
})
.catch(error => {
  console.error('Error loading sitemap:', error);
  document.write('Failed to load sitemap');
});
